public OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    while (!circulator.equals(stop)) {
        if (predicate.test(circulator.getFace())) {
            return circulator;
        }
        circulator.moveToNext();
    }
    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    while (circulator.hasNext()) {
        Node next = circulator.next();
        if (predicate.test(next)) {
            return circulator;
        } else if (next == stop) {
            return circulator;
        }
    }
    return null;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    Node current = start;
    Node next = start.getNeighbor(dir);
    while (current != stop && !predicate.test(current)) {
        current = next;
        next = current.getNeighbor(dir);
    }
    return new OuterFaceCirculator(current, stop);
}

