private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    for (K key : keys) {
        int lowerBound = Integer.MAX_VALUE;
        for (K otherKey : keys) {
            if (!key.equals(otherKey) && key.compareTo(otherKey) <= 0) {
                lowerBound = Math.min(lowerBound, otherKey.compareTo(key));
            }
        }
        lowerBounds.add(lowerBound);
    }
    return lowerBounds;
}

public List<Integer> computeLowerBounds(List<K> keys) {

    // Initialize the list of lower bounds with the smallest representable value
    List<Integer> lowerBounds = Collections.nCopies(keys.size(), Integer.MIN_VALUE);

    // Iterate through the list of keys and update the lower bounds accordingly
    for (int i = 0; i < keys.size(); i++) {
        int currentKey = keys.get(i);

        // If the current key is greater than the current lower bound, update the lower bound
        if (currentKey > lowerBounds.get(i)) {
            lowerBounds.set(i, currentKey);
        }
    }

    return lowerBounds;
}

