private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the graph has at least one edge
    if (graph.isEmpty()) {
        return false;
    }

    // Check if the set of vertices is a subset of the graph's vertices
    if (!graph.containsAll(vertices)) {
        return false;
    }

    // Check if the graph has a cycle
    if (graph.hasCycle()) {
        return false;
    }

    // Check if the graph is a clique
    for (V vertex : vertices) {
        for (E edge : graph.getEdges()) {
            if (!vertices.contains(edge.getOppositeVertex(vertex))) {
                return false;
            }
        }
    }

    return true;
}

public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1 != vertex2 && !graph.adjacent(vertex1, vertex2)) {
                return false;
            }
        }
    }
    return true;
}

public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the graph is null
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }

    // Check if the vertices set is null or empty
    if (vertices == null || vertices.isEmpty()) {
        throw new IllegalArgumentException("Vertices set cannot be null or empty");
    }

    // Check if the graph contains all the vertices
    if (!graph.containsAllVertices(vertices)) {
        throw new IllegalArgumentException("Graph must contain all vertices in the given set");
    }

    // Check if the graph is connected
    if (!graph.isConnected()) {
        throw new IllegalArgumentException("Graph must be connected");
    }

    // Check if the graph is a clique
    for (V vertex : vertices) {
        for (V neighbor : graph.getNeighbors(vertex)) {
            if (!vertices.contains(neighbor)) {
                return false;
            }
        }
    }

    return true;
}

