    Set<E> edges = new HashSet<>();
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 != v2 && !edges.contains(graph.getEdge(v1, v2))) {
                return false;
            }
        }
    }
    return true;
}

