    return FilenameUtils.normalize(path + File.separator + relativePath);
}

public static String applyRelativePath(String path, String relativePath) {
    // Split the path and relativePath into separate components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Remove the filename from the path
    pathComponents = pathComponents.slice(0, pathComponents.length - 1);

    // Add the relativePathComponents to the pathComponents
    String[] newPathComponents = pathComponents.concat(relativePathComponents);

    // If the last component of the path is not ".", add it to the new path components
    if (!pathComponents[pathComponents.length - 1].equals(".")) {
        newPathComponents = newPathComponents.concat(".");
    }

    // Join the new path components with "/" separators
    String newPath = newPathComponents.join("/");

    return newPath;
}

public static String applyRelativePath(String path, String relativePath) {
  // Check if the relativePath is not null and not empty
  if(relativePath != null && !relativePath.isEmpty()) {
      /* 
      Check if the relativePath starts with a forward slash, 
      if it does, it means the path is absolute 
      and we need to return the trimmed relativePath
      */
      if(relativePath.startsWith("/")) {
          return relativePath.trim();
      } else {
          /*
          Otherwise, the path is relative, so we need to combine the path and the relativePath
          We do this by trimming the relativePath and then adding it to the path using the forward slash
          */
          return path + "/" + relativePath.trim();
      }
  } else {
      /*
      If the relativePath is null or empty, it means we don't want to apply the relativePath
      so we just return the path as is
      */
      return path;
  }
}

public static String applyRelativePath(String path, String relativePath) {
    // First, we need to split the relativePath into its individual components
    String[] components = relativePath.split("/");

    // Next, we need to remove any ".." components from the start of the relativePath
    while (components[0].equals("..")) {
        components = Arrays.copyOfRange(components, 1);
    }

    // Finally, we can apply the relativePath to the given path
    for (String component : components) {
        path = component + "/" + path;
    }

    return path;
}

