public static long compressTimeBucket(long timeBucket, int dayStep) {
if (dayStep == 1) {
return timeBucket;
} else {
// Convert the timeBucket to a date
String dateString = Long.toString(timeBucket);
String formattedDateString = dateString.substring(0, 4) + "-" + dateString.substring(4, 6) + "-" + dateString.substring(6, 8);

// Parse the formatted date to a Date object
SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd");
Date parsedDate = dateFormat.parse(formattedDateString);

// Calculate the start of the dayStep
Calendar calendar = Calendar.getInstance();
calendar.setTime(parsedDate);
calendar.set(Calendar.DATE, dayStep);
Date startOfDayStep = calendar.getTime();

// Re-format the startOfDayStep to the expected format
String reFormattedDateString = dateFormat.format(startOfDayStep);
reFormattedDateString = reFormattedDateString.replaceAll("-", "");

// Convert the re-formatted date string to a long value
return Long.parseLong(reFormattedDateString);
}
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
	String timeBucketStr = String.valueOf(timeBucket);
	String compressedTimeBucketStr = timeBucketStr.substring(0, 6) + String.format("%02d", (Integer.parseInt(timeBucketStr.substring(6)) / dayStep) * dayStep);
	return Long.parseLong(compressedTimeBucketStr);
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    long day = (timeBucket / 100) % 100;
    long newDay = (day / dayStep) * dayStep + 1;
    return timeBucket - (day - newDay) * 100;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    Calendar calendar = Calendar.getInstance();
    calendar.setTimeInMillis(timeBucket);
    int dayOfMonth = calendar.get(Calendar.DAY_OF_MONTH);
    int lastDayOfMonth = calendar.getActualMaximum(Calendar.DAY_OF_MONTH);
    int step = lastDayOfMonth / dayStep;
    int newDayOfMonth = (dayOfMonth - 1) / step * step + 1;
    calendar.set(Calendar.DAY_OF_MONTH, newDayOfMonth);
    return calendar.getTimeInMillis();
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    long formattedTimeBucket = timeBucket;
    int datePart = (int) (formattedTimeBucket / 100L);
    int dayPart = (int) (formattedTimeBucket % 100L);
    int adjustedDayPart = (int) (dayPart / dayStep * 10) * dayStep;
    formattedTimeBucket = (long) (datePart * 100L) + (long) adjustedDayPart;
    return formattedTimeBucket;
}

